def transform(grid):
    h, w = len(grid), len(grid[0])

    # The first vertical divider follows the square pattern size.
    s = next((c for c, v in enumerate(grid[0]) if v == 5), 3)
    step = s + 1
    starts = []
    c = 0
    while c + s <= w:
        starts.append(c)
        c += step

    # Read the source patterns from the top band and their replacement
    # colors from the key row beneath the control band.
    templates = {}
    key_row = None
    for r in range(2 * s + 1, h):
        if any(grid[r][x] != 0 for x in range(w)):
            key_row = r
    if key_row is None:
        key_row = h - 1

    for x in starts:
        vals = [grid[r][c] for r in range(s) for c in range(x, x + s)
                if grid[r][c] not in (0, 5)]
        if not vals:
            continue
        source = max(set(vals), key=vals.count)
        replacements = [grid[key_row][c] for c in range(x, x + s)
                       if grid[key_row][c] not in (0, 5)]
        if replacements:
            templates[source] = (
                replacements[0],
                [[grid[r][x + c] == source for c in range(s)]
                 for r in range(s)]
            )

    out = [[0 for _ in range(s * s)] for _ in range(s * s)]
    for r in range(s):
        for x in starts:
            for c in range(s):
                source = grid[s + 1 + r][x + c]
                if source not in templates:
                    continue
                replacement, pattern = templates[source]
                for dr in range(s):
                    for dc in range(s):
                        if pattern[dr][dc]:
                            out[r * s + dr][c * s + dc] = replacement
    return out
